// setGenerationAnnotationOnVmi sets the VM generation annotation on the vmi. The
// annotation is merged into any existing annotations without removing them, and
// the annotations map is initialized when it is nil.
func setGenerationAnnotationOnVmi(generation int64, vmi *virtv1.VirtualMachineInstance) {
	annotations := vmi.GetAnnotations()
	if annotations == nil {
		annotations = map[string]string{}
	}
	setGenerationAnnotation(generation, annotations)
	vmi.SetAnnotations(annotations)
}

// getGenerationAnnotation returns a pointer to the string value of the VM
// generation annotation on the vmi if it exists, or (nil, nil) if the
// annotation is absent or the annotations map is empty.
func getGenerationAnnotation(vmi *virtv1.VirtualMachineInstance) (*string, error) {
	if vmi == nil {
		return nil, errors.New("received nil pointer for vmi")
	}

	currentGenerationStr, ok := vmi.Annotations[virtv1.VirtualMachineGenerationAnnotation]
	if ok {
		return &currentGenerationStr, nil
	}

	return nil, nil
}

// getGenerationAnnotationAsInt returns a pointer to the int64 value of the VM
// generation annotation on the vmi. If the annotation is absent or contains a
// malformed (non-integer) value, (nil, nil) is returned so the caller can treat
// it as missing.
func getGenerationAnnotationAsInt(vmi *virtv1.VirtualMachineInstance, logger *log.FilteredLogger) (*int64, error) {
	currentGenerationStr, err := getGenerationAnnotation(vmi)
	if err != nil {
		return nil, err
	}
	if currentGenerationStr == nil {
		return nil, nil
	}

	generation, err := strconv.ParseInt(*currentGenerationStr, 10, 64)
	if err != nil {
		if logger != nil {
			logger.Reason(err).Errorf("Failed to parse generation annotation %q as an int", *currentGenerationStr)
