	}

	return &generation, nil
}

// getControllerRevision fetches the ControllerRevision with the given name from
// the Kubernetes API. It returns (nil, nil) if the ControllerRevision does not
// exist.
func (c *Controller) getControllerRevision(namespace, name string) (*appsv1.ControllerRevision, error) {
	cr, err := c.clientset.AppsV1().ControllerRevisions(namespace).Get(context.Background(), name, metav1.GetOptions{})
	if err != nil {
		if apiErrors.IsNotFound(err) {
			return nil, nil
		}
		return nil, err
	}
	return cr, nil
}

// patchVmGenerationAnnotationOnVmi patches the vmi in the Kubernetes API to set
// the VM generation annotation to the given generation formatted as a decimal
// string. The patched vmi is returned.
func (c *Controller) patchVmGenerationAnnotationOnVmi(generation int64, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
	oldAnnotations := vmi.Annotations
	newAnnotations := maps.Clone(oldAnnotations)
	if newAnnotations == nil {
		newAnnotations = map[string]string{}
	}
	setGenerationAnnotation(generation, newAnnotations)

	patchSet := patch.New()
	if len(oldAnnotations) == 0 {
		patchSet.AddOption(patch.WithAdd("/metadata/annotations", newAnnotations))
	} else {
		patchSet.AddOption(
			patch.WithTest("/metadata/annotations", oldAnnotations),
			patch.WithReplace("/metadata/annotations", newAnnotations),
		)
	}

	patchBytes, err := patchSet.GeneratePayload()
	if err != nil {
		return vmi, err
	}

	patchedVMI, err := c.clientset.VirtualMachineInstance(vmi.Namespace).Patch(context.Background(), vmi.Name, types.JSONPatchType, patchBytes, v1.PatchOptions{})
	if err != nil {
		return vmi, err
	}

	return patchedVMI, nil
}

