	}

	cr, err := c.getControllerRevision(vmi.Namespace, vmi.Status.VirtualMachineRevisionName)
	if err != nil || cr == nil {
		return vmi, err
	}

	revisionData := VirtualMachineRevisionData{}
	if err = json.Unmarshal(cr.Data.Raw, &revisionData); err != nil {
		return vmi, err
